const $=s=>document.querySelector(s),dialog=$('#game-dialog'),area=$('#game-area'),status=$('#status');let current='',timer=null,version=0,bests={};try{bests=JSON.parse(localStorage.getItem('play-lab-bests'))||{}}catch{}const units={reaction:'ms',memory:'手',puzzle:'手'};function refresh(){for(const k of Object.keys(units))$('#best-'+k).textContent='BEST '+(bests[k]?bests[k]+' '+units[k]:'—')}function record(k,n){if(!bests[k]||n<bests[k]){bests[k]=n;try{localStorage.setItem('play-lab-bests',JSON.stringify(bests))}catch{}refresh();return true}return false}refresh();function cancel(){clearTimeout(timer);version++}const info={reaction:['01 / REFLEX','クイック・タップ','スタートを押して待機。パネルが緑になったらすぐタップ！スペースキーでも遊べます。'],memory:['02 / MEMORY','ペア・ファインダー','カードを2枚ずつめくって、同じマークをそろえよう。全6ペアを少ない手数で見つけてください。'],puzzle:['03 / PUZZLE','スライド・エイト','空白の隣の数字をタップして移動。1〜8を左上から順番に並べよう。矢印キーで空白を移動できます。']};function start(){cancel();status.textContent='';area.replaceChildren();$('#restart').textContent='最初から遊ぶ ↻';const [type,title,rules]=info[current];$('#game-type').textContent=type;$('#game-title').textContent=title;$('#rules').textContent=rules;if(current==='reaction')reaction();if(current==='memory')memory();if(current==='puzzle')puzzle()}document.querySelectorAll('[data-game]').forEach(b=>b.addEventListener('click',()=>{current=b.dataset.game;start();dialog.showModal()}));$('#restart').onclick=start;$('#close').onclick=()=>dialog.close();dialog.addEventListener('close',cancel);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function reaction(){const b=document.createElement('button');b.className='reaction-pad';b.textContent='スタート →';area.append(b);let state='idle',now=0;b.onclick=()=>{if(state==='idle'||state==='done'){state='wait';b.className='reaction-pad wait';b.textContent='まだ… 緑を待って！';status.textContent='';timer=setTimeout(()=>{state='go';now=performance.now();b.className='reaction-pad go';b.textContent='今！ TAP';},1500+Math.random()*2500)}else if(state==='wait'){clearTimeout(timer);state='done';b.className='reaction-pad';b.textContent='早すぎました！ 再挑戦 →';status.textContent='フライング。緑になるまで待とう。'}else{const ms=Math.max(1,Math.round(performance.now()-now));state='done';b.className='reaction-pad';b.textContent=ms+' ms · もう一度 →';status.textContent=record('reaction',ms)?'自己ベスト更新！':'ナイス！ もう一度挑戦してみよう。'}};b.focus()}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}function memory(){const items=shuffle(['★','●','◆','▲','☀','✿','★','●','◆','▲','☀','✿']);const board=document.createElement('div');board.className='board memory';area.append(board);let picks=[],moves=0,pairs=0,locked=false;const v=version;status.textContent='0手 / 0 of 6 ペア';items.forEach((symbol,i)=>{const b=document.createElement('button');b.className='tile';b.textContent='?';b.setAttribute('aria-label','カード'+(i+1)+'をめくる');board.append(b);b.onclick=()=>{if(locked||b.classList.contains('revealed')||b.classList.contains('matched'))return;b.textContent=symbol;b.classList.add('revealed');b.setAttribute('aria-label',symbol);picks.push(b);if(picks.length===2){moves++;if(picks[0].textContent===picks[1].textContent){picks.forEach(x=>{x.classList.remove('revealed');x.classList.add('matched');x.disabled=true});pairs++;picks=[];status.textContent=moves+'手 / '+pairs+' of 6 ペア';if(pairs===6)status.textContent='完成！ '+moves+'手'+(record('memory',moves)?' · 自己ベスト更新！':'')}else{locked=true;status.textContent=moves+'手 / '+pairs+' of 6 ペア';timer=setTimeout(()=>{if(version!==v)return;picks.forEach(x=>{x.textContent='?';x.classList.remove('revealed');x.setAttribute('aria-label','カードをめくる')});picks=[];locked=false},850)}}}})}
let puzzleMove=null;function puzzle(){let cells=[1,2,3,4,5,6,7,8,0],moves=0,done=false,prev=-1;const neighbors=z=>[z-3,z+3,z%3?z-1:-1,z%3<2?z+1:-1].filter(n=>n>=0&&n<9);for(let n=0;n<100;n++){const z=cells.indexOf(0),opts=neighbors(z).filter(i=>i!==prev),i=opts[Math.floor(Math.random()*opts.length)];[cells[z],cells[i]]=[cells[i],cells[z]];prev=z}if(cells.every((x,i)=>x===(i+1)%9)){[cells[7],cells[8]]=[cells[8],cells[7]]}const board=document.createElement('div');board.className='board puzzle';area.append(board);function render(){board.replaceChildren();cells.forEach((num,i)=>{const b=document.createElement('button');b.className='tile'+(num===0?' empty':'');b.textContent=num||'';b.disabled=num===0||done;b.setAttribute('aria-label',num?'数字'+num+'を移動':'空白');b.onclick=()=>move(i);board.append(b)});status.textContent=moves+'手'}function move(i){if(done)return;const z=cells.indexOf(0);if(!neighbors(z).includes(i))return;[cells[z],cells[i]]=[cells[i],cells[z]];moves++;done=cells.every((x,i)=>x===(i+1)%9);render();if(done)status.textContent='完成！ '+moves+'手'+(record('puzzle',moves)?' · 自己ベスト更新！':'')}puzzleMove=key=>{const z=cells.indexOf(0);const i={ArrowUp:z-3,ArrowDown:z+3,ArrowLeft:z%3?z-1:-1,ArrowRight:z%3<2?z+1:-1}[key];move(i)};render()}
document.addEventListener('keydown',e=>{if(!dialog.open||e.target.closest('#close,#restart'))return;if(current==='puzzle'&&e.key.startsWith('Arrow')){e.preventDefault();puzzleMove(e.key)}if(current==='reaction'&&e.code==='Space'&&!e.repeat){e.preventDefault();$('.reaction-pad').click()}});
